     1	package service;
     2	
     3	import util.Money;
     4	
     5	import java.util.ArrayList;
     6	import java.util.List;
     7	
     8	/**
     9	 * Spreads an order-level coupon over the lines in proportion to price (floor),
    10	 * the leftover won goes to the first most expensive line. A partial refund
    11	 * returns what the customer actually paid for that line.
    12	 */
    13	public final class DiscountAllocator {
    14	    private DiscountAllocator() {}
    15	
    16	    public static List<Long> allocate(List<Long> prices, long coupon) {
    17	        List<Long> out = new ArrayList<>();
    18	        if (prices.isEmpty()) return out;
    19	        long total = prices.stream().mapToLong(Long::longValue).sum();
    20	        if (coupon < 0 || coupon > total) throw new IllegalArgumentException("coupon out of range: " + coupon);
    21	        long given = 0;
    22	        int top = 0;
    23	        for (int i = 0; i < prices.size(); i++) {
    24	            long d = coupon == 0 ? 0 : Money.share(coupon, prices.get(i), total);
    25	            out.add(d);
    26	            given += d;
    27	            if (prices.get(i) > prices.get(top)) top = i;
    28	        }
    29	        out.set(top, out.get(top) + (coupon - given));
    30	        return out;
    31	    }
    32	}

