/**
 * Merchant reference printed on the PG settlement file so finance can trace the refund to our order line.
 * The PG treats lines with the same TID, amount and reference as one refund, so it must identify the line,
 * not just the order: two identical items in one order share the order number.
 */
public static String merchantRef(RefundLine line) {
    return Refs.sanitize(line.orderNo() + "-" + line.lineNo());
}

